using System.Security.Claims;using Microsoft.AspNetCore.Mvc;using Topstar.Application.Disputes;using Topstar.Application.Profiles;
namespace Topstar.Web.Pages.Brand;public sealed class DisputesModel(IProfileAccessService access,IDisputeService service):BrandGuardedPageModel(access){
 [BindProperty(SupportsGet = true)] public Guid? CampaignId { get; set; }
 public Topstar.Application.Common.ListWindow Window { get; private set; } = new();
public DisputePortal Portal{get;private set;}=new([],[]);[TempData]public string? Message{get;set;}[TempData]public bool MessageSuccess{get;set;}public async Task<IActionResult> OnGetAsync(CancellationToken ct){ Window = Topstar.Web.Features.Common.Paging.ListWindowRequest.Read(Request,"brandDisputeTable");var r=await RedirectIfProfileIncompleteAsync(false);if(r is not null)return r;Portal=await service.GetPortalAsync(UserId(),true,ct, Window,CampaignId);return Page();}public Task<IActionResult> OnPostOpenAsync(Guid participationId,string category,string subject,string description,CancellationToken ct)=>Run(()=>service.OpenAsync(UserId(),true,participationId,category,subject,description,ct));public Task<IActionResult> OnPostCancelAsync(Guid id,string reason,CancellationToken ct)=>Run(()=>service.CancelAsync(UserId(),id,reason,ct));private async Task<IActionResult> Run(Func<Task<DisputeResult>> a){var r=await RedirectIfProfileIncompleteAsync(false);if(r is not null)return r;var x=await a();Message=x.Message;MessageSuccess=x.Success;return RedirectToPage(new {campaignId=CampaignId});}private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
